const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial={id:'demo',name:'Slider-crank mechanism',kind:'Mechanical assembly',stroke:80,rod:150,rpm:600,material:'Aluminium 6061',parts:[{name:'Crankshaft',material:'Steel',qty:1,price:1200},{name:'Connecting rod',material:'Aluminium 6061',qty:1,price:650},{name:'Piston & guide',material:'Aluminium 6061',qty:1,price:850},{name:'Bearing',material:'Steel',qty:2,price:240}],notes:[],revisions:[]};
let projects;try{projects=JSON.parse(localStorage.getItem('engineering-studio-v1'))||[structuredClone(initial)]}catch{projects=[structuredClone(initial)]}let current=projects[0],page='design',selected=0,running=false,exploded=false,angle=0,timer;
const tabs=[['design','Design'],['assembly','Assembly'],['electronics','Electronics'],['analysis','Analysis'],['cost','BOM & cost'],['evidence','Evidence'],['revisions','Revisions']];
function persist(){localStorage.setItem('engineering-studio-v1',JSON.stringify(projects));$('#saved').textContent='● Saved on this device'}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function field(name,label,value,type='text'){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="1" required':''}></div>`}function modal(title,fields,submit){$('#modalTitle').textContent=title;$('#modalFields').innerHTML=fields;$('#modalForm').onsubmit=e=>{e.preventDefault();submit(new FormData(e.target));$('#dialog').close()};$('#dialog').showModal()}$('#closeDialog').onclick=()=>$('#dialog').close();
function total(){return current.parts.reduce((s,p)=>s+p.qty*p.price,0)}const money=n=>'₹'+n.toLocaleString('en-IN',{maximumFractionDigits:0});
function machine(){let x=exploded?40:0;return `<svg class="machine" viewBox="0 0 650 370" role="img" aria-label="Interactive slider crank educational mechanism"><defs><linearGradient id="metal" x2="0.8" y2="1"><stop stop-color="#e9eee2"/><stop offset=".5" stop-color="#b9c5ac"/><stop offset="1" stop-color="#859779"/></linearGradient><linearGradient id="dark" x2=".8" y2="1"><stop stop-color="#9ca98e"/><stop offset="1" stop-color="#526c49"/></linearGradient><filter id="shadow"><feDropShadow dx="0" dy="12" stdDeviation="10" flood-opacity=".13"/></filter></defs><g opacity=".35" stroke="#b8c3ac" fill="none"><path d="M60 290L355 345L610 230M355 345V80M60 290L300 170L610 230"/><path stroke-dasharray="4 5" d="M100 240L550 150"/></g><g filter="url(#shadow)"><path d="M110 240L340 280L540 183L310 145Z" fill="#c6d0ba" stroke="#94a585"/><path d="M110 240V263L340 306V280Z" fill="#91a180"/><path d="M340 280L540 183V205L340 306Z" fill="#a8b799"/><g transform="translate(${-x},0)"><path d="M183 222V151L220 134L251 143V235L221 250Z" fill="url(#dark)" stroke="#718764"/><ellipse cx="222" cy="177" rx="19" ry="32" fill="#4b6540"/><ellipse cx="222" cy="177" rx="11" ry="21" fill="#c0cbb3"/></g><g id="wheel"><ellipse cx="322" cy="184" rx="59" ry="78" fill="#6e835f" stroke="#4e6744" stroke-width="2"/><ellipse cx="313" cy="180" rx="59" ry="78" fill="url(#metal)" stroke="#889d78"/><ellipse cx="313" cy="180" rx="43" ry="58" fill="#a1b28f" stroke="#839971"/><ellipse cx="313" cy="180" rx="12" ry="17" fill="#536d46"/><path d="M313 180L291 142" stroke="#ced8c1" stroke-width="17" stroke-linecap="round"/><ellipse cx="291" cy="142" rx="8" ry="11" fill="#536d46"/></g><g transform="translate(${x},${-x/2})"><path d="M291 142L430 105L442 122L300 160Z" fill="url(#metal)" stroke="#839871"/><ellipse cx="435" cy="114" rx="9" ry="13" fill="#718861"/><path d="M418 76L464 61L490 73V140L444 159L418 143Z" fill="url(#metal)" stroke="#91a37e"/><path d="M444 92L490 73V140L444 159Z" fill="#8fa47d"/><path d="M418 76L444 92L490 73L464 61Z" fill="#dce5cf"/><path d="M405 176L506 129L520 137L420 186Z" fill="#748b63"/><path d="M405 176L420 186V207L405 198Z" fill="#8b9d7c"/><path d="M420 186L520 137V158L420 207Z" fill="#adbd9b"/></g><circle cx="147" cy="242" r="4" fill="#7e9170"/><circle cx="337" cy="278" r="4" fill="#7e9170"/></g><g fill="#718465" font-family="sans-serif" font-size="10"><path d="M460 55L500 33H560" stroke="#9aaa8b" fill="none"/><text x="504" y="27">Piston & guide</text><path d="M300 252L265 302H185" stroke="#9aaa8b" fill="none"/><text x="185" y="318">Crankshaft</text></g></svg>`}
function card(title,body,extra=''){return `<section class="card ${extra}"><div class="cardHead"><h2>${title}</h2></div>${body}</section>`}
function render(){running=false;$('#title').textContent=page==='projects'?'Your engineering workspace':current.name;$('#crumbTitle').textContent=current.name;$('#tabs').innerHTML=page==='projects'?'':tabs.map(([id,n])=>`<button class="tab ${page===id?'active':''}" data-tab="${id}">${n}</button>`).join('');$('#projectNav').innerHTML=projects.map(p=>`<button class="projectLink ${p===current?'selected':''}" data-project="${esc(p.id)}">${esc(p.name)}</button>`).join('');document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.page===(['projects','evidence'].includes(page)?page:'design')));let html='';
if(page==='design')html=`<div class="designGrid"><section class="card"><div class="cardHead"><h2>Assembly viewport <span class="tiny"> / Concept view</span></h2><span class="pill">${current.parts.length} components</span></div><div class="viewport"><div class="viewLabel">PERSPECTIVE<span>Educational mechanism · illustrative geometry</span></div><div class="axis">Y ↑<br>↙ X &nbsp; Z ↗</div><div class="viewTools"><button title="Zoom in" id="zoomIn">＋</button><button title="Zoom out" id="zoomOut">−</button><button title="Reset view" id="resetView">⌖</button></div>${machine()}<div class="viewBottom"><div><button id="animate">▷ Animate</button> <button id="explode">${exploded?'Assemble':'Exploded view'}</button></div><span>Concept illustration · not CAD geometry</span></div></div><div class="propertyFoot">◈ Parameter changes update calculations, cost records, and revision state.</div></section><section class="card"><div class="cardHead"><h2>Design parameters</h2><span class="tiny">mm</span></div><div class="properties">${field('stroke','Stroke',current.stroke,'number')}${field('rod','Connecting rod length',current.rod,'number')}${field('rpm','Rotational speed · RPM',current.rpm,'number')}<div class="field"><label for="material">Material</label><select id="material">${['Aluminium 6061','Steel','ABS polymer'].map(m=>`<option ${m===current.material?'selected':''}>${m}</option>`).join('')}</select></div><button class="primary" id="apply" style="width:100%">Apply parameters ↗</button></div><div class="propertyFoot">Manual control. Every change is yours.</div></section></div><div class="lower"><section class="card"><div class="cardHead"><h2>Assembly structure</h2><button data-tab="assembly">View all ↗</button></div><div class="list">${current.parts.slice(0,4).map(p=>`<div class="listrow"><span><span class="dot">◇</span>${esc(p.name)}</span><small>× ${p.qty} &nbsp; ${esc(p.material)}</small></div>`).join('')||'<p>No components yet. Add one in Assembly.</p>'}</div></section><section class="card assistant"><div class="cardHead"><h2>✧ Engineering guide</h2><span class="tiny">LOCAL GUIDANCE</span></div><div class="assistantBody"><p id="answer">Start with a question about your mechanism. Explore the design assumptions before taking the next step.</p><form id="guide"><div class="promptrow"><input id="question" aria-label="Ask engineering guide" placeholder="How does this mechanism work?" required><button class="primary" aria-label="Send question">↗</button></div></form><div class="suggestions"><button data-question="Explain the mechanism">Explain mechanism</button><button data-question="Check my dimensions">Check dimensions</button><button data-question="How is cost calculated?">Review cost</button></div></div></section></div><div class="metrics">${[['COMPONENTS',current.parts.reduce((s,p)=>s+p.qty,0),'Across '+current.parts.length+' unique parts'],['SWEPT TRAVEL',current.stroke+' mm','Ideal slider displacement'],['PLANNING ESTIMATE',money(total()),'Components only · unquoted'],['LATEST REVISION',current.revisions.length?'R'+String(current.revisions.length).padStart(2,'0'):'Unsaved','Save a snapshot to compare']].map(([a,b,c])=>`<div class="card metric"><label>${a}</label><strong>${b}</strong><small>${c}</small></div>`).join('')}</div>`;
if(page==='projects')html=`<div class="actions"><p>Original ideas, connected from the start.</p><button class="primary" id="createProject">＋ Create project</button></div><div class="cards">${projects.map(p=>`<button class="card projectCard" data-project="${esc(p.id)}"><span class="pill">ENGINEERING CONCEPT</span><h2>${esc(p.name)}</h2><p>${esc(p.kind)} · ${p.parts.length} components</p><span class="tiny">Open workspace ↗</span></button>`).join('')}</div>`;
if(page==='assembly'||page==='cost')html=`<section class="card pageCard"><div class="actions"><div><h2>${page==='cost'?'Bill of materials & cost':'Assembly components'}</h2><p class="tiny">Editable components · quantities · materials · planning prices</p></div><button class="primary" id="addPart">＋ Add component</button></div><div class="tableWrap"><table><thead><tr><th>COMPONENT</th><th>MATERIAL</th><th>QUANTITY</th><th>UNIT COST</th><th>SUBTOTAL</th><th></th></tr></thead><tbody>${current.parts.map((p,i)=>`<tr><td>${esc(p.name)}</td><td>${esc(p.material)}</td><td><input aria-label="Quantity for ${esc(p.name)}" type="number" min="1" data-qty="${i}" value="${p.qty}"></td><td>${money(p.price)}</td><td>${money(p.qty*p.price)}</td><td><button data-edit="${i}" aria-label="Edit ${esc(p.name)}">Edit</button> <button data-delete="${i}" aria-label="Remove ${esc(p.name)}">×</button></td></tr>`).join('')}</tbody></table></div><div class="actions" style="margin-top:25px"><button id="csv">↓ Export BOM · CSV</button><h2>Planning estimate &nbsp; ${money(total())}</h2></div><div class="note">Planning estimate in INR. Prices are manually entered assumptions; supplier quotations, tax, delivery, tooling, labor, finishing, inspection and uncertainty are not included. No live supplier pricing is connected.</div></section>`;
if(page==='analysis'){let valid=current.rod>current.stroke/2;html=card('Engineering evaluation',`<div class="check"><span class="pill">${valid?'PASS':'FAIL'}</span><h3 style="margin-top:12px">Ideal slider-crank geometry</h3><p>Rod length ${current.rod} mm ${valid?'>':'≤'} crank radius ${current.stroke/2} mm. ${valid?'The ideal linkage can complete a rotation.':'Increase rod length to exceed the crank radius.'} This does not verify real assembly clearances.</p></div><div class="check"><span class="pill">CALCULATED</span><h3 style="margin-top:12px">Mean piston speed: ${(2*(current.stroke/1000)*current.rpm/60).toFixed(2)} m/s</h3><p>2 × stroke (m) × RPM / 60. Ideal kinematic calculation; no loads or friction included.</p></div><div class="check"><span class="tag">UNKNOWN</span><h3 style="margin-top:12px">Structural, thermal & electrical verification</h3><p>Requires specialist solver integrations, boundary conditions, material models and validated benchmarks. No solver results are claimed.</p></div><div class="check"><button id="recordCheck">Record calculation in evidence</button></div>`)}
if(page==='electronics')html=`<div class="lower" style="margin-top:0">${card('Electronics & control notes',`<div class="properties"><p class="tiny">Document power, wiring, connectors and firmware requirements.</p><div class="field"><label for="electrical">Project electrical specification</label><textarea id="electrical" placeholder="Supply voltage, motor driver, connectors, firmware…">${esc(current.electrical||'')}</textarea></div><button class="primary" id="saveElectrical">Save specification</button></div>`)}${card('Connected workflow',`<div class="properties"><h3>From mechanism to control</h3><p>Add motors, drivers and purchased electronics through the assembly table. Track wiring requirements here and test findings in Evidence.</p><div class="note">Schematic capture, circuit simulation and firmware execution require further integration. This version supports specification notes and component tracking.</div></div>`)}</div>`;
if(page==='evidence')html=`<section class="card pageCard"><div class="actions"><div><h2>Research & evidence</h2><p class="tiny">Keep assumptions, calculations and test observations attached to the project.</p></div><button class="primary" id="addNote">＋ Add evidence</button></div>${current.notes.length?current.notes.map(n=>`<article class="check"><span class="tiny">${esc(n.date)} · ${esc(n.type)}</span><h3 style="margin-top:10px">${esc(n.title)}</h3><p style="white-space:pre-wrap">${esc(n.body)}</p></article>`).join(''):'<div class="empty">No evidence recorded yet.<p>Add a research note or record a calculation from Analysis.</p></div>'}<div class="note">Current maturity: Engineering concept. Reviewed design, fabrication package and physically tested revision require supporting evidence and qualified review.</div></section>`;
if(page==='revisions')html=card('Project revisions',current.revisions.length?[...current.revisions].reverse().map((r,i)=>`<div class="revision"><div><h3>R${String(current.revisions.length-i).padStart(2,'0')} · ${esc(r.label)}</h3><p>${esc(r.date)} · ${r.snapshot.parts.length} component types · ${r.snapshot.stroke} mm stroke</p></div><button data-restore="${current.revisions.length-1-i}">Restore snapshot</button></div>`).join(''):'<div class="empty">No saved revisions.<p>Use “Save revision” to capture a recoverable project snapshot.</p></div>');$('#content').innerHTML=html;bind()}
function navigate(p){page=p;render()}document.addEventListener('click',e=>{let t=e.target.closest('[data-tab],[data-page],[data-project]');if(!t)return;if(t.dataset.project){current=projects.find(p=>p.id===t.dataset.project);selected=0;page='design';render()}else navigate(t.dataset.tab||t.dataset.page)});
function download(name,data,type){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}$('#export').onclick=()=>download(current.name+'.json',JSON.stringify(current,null,2),'application/json');
function newProject(){modal('Create a project',field('name','Project name','')+'<div class="field"><label for="kind">Discipline</label><select name="kind" id="kind"><option>Mechanical assembly</option><option>Electromechanical prototype</option><option>Electronics project</option></select></div>',f=>{if(!f.get('name').trim())return;current={...structuredClone(initial),id:crypto.randomUUID(),name:f.get('name').trim(),kind:f.get('kind'),parts:[],notes:[],revisions:[]};projects.push(current);persist();page='design';render();toast('Project created')})}$('#newProject').onclick=newProject;
$('#saveRevision').onclick=()=>modal('Save project revision',field('label','Revision description','Design iteration'),f=>{let snapshot=structuredClone(current);delete snapshot.revisions;current.revisions.push({label:f.get('label')||'Design iteration',date:new Date().toLocaleString(),snapshot});persist();render();toast('Recoverable revision saved')});
function editPart(i){let p=i===undefined?{name:'',material:'Aluminium 6061',qty:1,price:0}:current.parts[i];modal(i===undefined?'Add component':'Edit component',field('name','Component name',p.name)+field('material','Material / specification',p.material)+field('qty','Quantity',p.qty,'number')+field('price','Unit planning price · INR',p.price,'number'),f=>{if(!f.get('name').trim())return;let part={name:f.get('name'),material:f.get('material'),qty:+f.get('qty'),price:+f.get('price')};if(i===undefined)current.parts.push(part);else current.parts[i]=part;persist();render()});$('#price').min='0'}
function guide(q){let a=/cost|price|bom/i.test(q)?`Your current component planning total is ${money(total())}. It excludes labor, tooling, taxes and delivery. Enter supplier prices in BOM & cost and keep dated quotations in Evidence.`:/dimension|check|rod|stroke/i.test(q)?`Crank radius is ${current.stroke/2} mm. Your ${current.rod} mm rod ${current.rod>current.stroke/2?'exceeds':'does not exceed'} the radius. Mean piston speed is ${(2*current.stroke/1000*current.rpm/60).toFixed(2)} m/s. These ideal calculations do not establish strength or clearances.`:/mechanism|work|explain/i.test(q)?'A rotating crank drives a connecting rod, converting rotation into reciprocating piston motion. Stroke is twice the crank radius. The animation is illustrative; use Analysis for parameter-based calculations.':'This local guide supports mechanism explanations, dimension checks, and planning-cost questions. A live AI service is not connected yet. Record additional research in Evidence.';$('#answer').textContent=a}
function bind(){if($('#apply'))$('#apply').onclick=()=>{let values=['stroke','rod','rpm'].map(k=>+$('#'+k).value);if(values.some(v=>!Number.isFinite(v)||v<=0)){toast('Enter positive dimensions and speed');return}['stroke','rod','rpm'].forEach((k,i)=>current[k]=values[i]);current.material=$('#material').value;persist();render();toast('Parameters and calculations updated')};if($('#animate'))$('#animate').onclick=()=>{running=!running;$('#animate').textContent=running?'Ⅱ Pause':'▷ Animate';if(running)requestAnimationFrame(frame)};if($('#explode'))$('#explode').onclick=()=>{exploded=!exploded;render()};let zoom=1;for(let [id,delta] of [['zoomIn',.15],['zoomOut',-.15],['resetView',0]])if($('#'+id))$('#'+id).onclick=()=>{zoom=delta?Math.max(.6,Math.min(1.6,zoom+delta)):1;$('.machine').style.transform=`scale(${zoom})`};if($('#guide'))$('#guide').onsubmit=e=>{e.preventDefault();guide($('#question').value)};document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>guide(b.dataset.question));if($('#createProject'))$('#createProject').onclick=newProject;if($('#addPart'))$('#addPart').onclick=()=>editPart();document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editPart(+b.dataset.edit));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{current.parts.splice(+b.dataset.delete,1);persist();render();toast('Component removed')});document.querySelectorAll('[data-qty]').forEach(b=>b.onchange=()=>{if(+b.value<1||!Number.isInteger(+b.value)){toast('Quantity must be a positive integer');render();return}current.parts[+b.dataset.qty].qty=+b.value;persist();render()});if($('#csv'))$('#csv').onclick=()=>{const cell=v=>'"'+String(v).replace(/"/g,'""')+'"';download('bill-of-materials.csv',[['Component','Material','Quantity','Unit cost INR','Subtotal INR'],...current.parts.map(p=>[p.name,p.material,p.qty,p.price,p.qty*p.price])].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv')};if($('#saveElectrical'))$('#saveElectrical').onclick=()=>{current.electrical=$('#electrical').value;persist();toast('Electrical specification saved')};if($('#addNote'))$('#addNote').onclick=()=>modal('Add research evidence',field('title','Title','')+'<div class="field"><label for="type">Evidence type</label><select id="type" name="type"><option>Research note</option><option>Assumption</option><option>Physical test observation</option><option>Supplier quotation note</option></select></div><div class="field"><label for="body">Findings / source / conditions</label><textarea id="body" name="body" required></textarea></div>',f=>{current.notes.push({title:f.get('title')||'Research note',body:f.get('body'),type:f.get('type'),date:new Date().toLocaleString()});persist();render()});if($('#recordCheck'))$('#recordCheck').onclick=()=>{current.notes.push({title:'Ideal kinematic calculation',type:'Calculated · not physically validated',date:new Date().toLocaleString(),body:`Stroke: ${current.stroke} mm; rod: ${current.rod} mm; speed: ${current.rpm} RPM. Mean piston speed: ${(2*current.stroke/1000*current.rpm/60).toFixed(2)} m/s. Rod > crank radius: ${current.rod>current.stroke/2}. No load or friction model.`});persist();toast('Calculation recorded in evidence')};document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>{let r=current.revisions[+b.dataset.restore],revisions=current.revisions;Object.assign(current,structuredClone(r.snapshot),{revisions});persist();render();toast('Revision restored')})}
function frame(){if(!running||!$('#wheel'))return;angle=(angle+2)%360;$('#wheel').setAttribute('transform',`rotate(${Math.sin(angle*Math.PI/180)*12} 313 180)`);requestAnimationFrame(frame)}render();
